    def _get(self, path: str, params: Optional[dict] = None) -> Any:
        response = self.session.get(f"{BASE_URL}{path}", params=params)
        response.raise_for_status()
        return response.json()

    def _post(self, path: str, json: Optional[dict] = None, params: Optional[dict] = None) -> Any:
        response = self.session.post(f"{BASE_URL}{path}", json=json, params=params)
        response.raise_for_status()
        return response.json()

    def _put(self, path: str, json: Optional[dict] = None) -> Any:
        response = self.session.put(f"{BASE_URL}{path}", json=json)
        response.raise_for_status()
        return response.json()

